// ===== COMPONENTE PRINCIPALE =====
export default function ModuloIntervento({ cliente, onClose, datiIniziali = null, solaLettura = false }) {
  const oggi = new Date();
  const dataOggi = oggi.toISOString().split("T")[0];
  const oraOggi = oggi.toLocaleTimeString("it-IT", { hour: "2-digit", minute: "2-digit" });

  const [dati, setDati] = useState(datiIniziali ?? {
    richiestaNum: "",
    dataRichiesta: dataOggi,
    ora: oraOggi,
    sedeCliente: cliente?.indirizzo || "",
    capSede: cliente?.cap || "",
    comuneSede: cliente?.citta || "",
    provSede: "",
    ubicazione: cliente?.indirizzo || "",
    capUbicazione: cliente?.cap || "",
    comuneUbicazione: cliente?.citta || "",
    provUbicazione: "",
    codFiscale: "",
    rifSDI: "",
    pec: "",
    marcaRT: "",
    modelloRT: cliente?.modello || "",
    matricolaRT: cliente?.matricola || "",
    ultimoFirmware: "",
    ubicazioneFissa: true,
    interventoRichiesto: "",
    descrizioneIntervento: "",
    luogoIntervento: "cliente",
    riferimentiCommerciali: "pagamento",
    rifFatturaGaranzia: "",
    dataGaranzia: "",
    scadenzaAbbonamento: "",
    reparti: [
      { n: "1", descrizione: "", naturaIVA: "", aliquota: "", bene: false, servizio: false, ateco: "" },
      { n: "2", descrizione: "", naturaIVA: "", aliquota: "", bene: false, servizio: false, ateco: "" },
      { n: "3", descrizione: "", naturaIVA: "", aliquota: "", bene: false, servizio: false, ateco: "" },
      { n: "4", descrizione: "", naturaIVA: "", aliquota: "", bene: false, servizio: false, ateco: "" },
    ],
    dirittoDiChiamata: "",
    orelavoro: "",
    costoOrario: "",
    ricambi: [
      { articolo: "", qta: "", prezzo: "" },
      { articolo: "", qta: "", prezzo: "" },
      { articolo: "", qta: "", prezzo: "" },
    ],
    verificazionePeriodica: false,
    totaleIntervento: "",
    esito: "positivo",
    pagamento: true,
    motivazioneMancatoPagamento: "",
    valOperatori: "",
    valServizio: "",
    valQualitaPrezzo: "",
    rappresentante: "",
    vp: {
      nomeUtente: cliente?.azienda || "",
      pivaUtente: cliente?.piva || "",
      modelloRT: cliente?.modello || "",
      matricolaRT: cliente?.matricola || "",
      check: {},
      tipoSigillo: "targhetta",
      versioneFirmwareRT: "",
      versioneInstallata: "",
      docChiusura: "",
      scadenzaVP: "",
      dataVP: dataOggi,
      esitoVP: "positivo",
      areePubliche: false,
    }
  });

  const [tab, setTab] = useState("rapporto");
  const [savedToast, setSavedToast] = useState(null);
  const canvasClienteRef = useRef(null);
  const canvasClienteVPRef = useRef(null);
  const isDrawingRef = useRef(false);








 async function salvaStorico() {
  try {
    const nuovoIntervento = {
      pivaCliente: cliente?.piva || "",
      aziendaCliente: cliente?.azienda || "",
      dataSalvataggio: new Date().toISOString(),
      tipoIntervento: dati.interventoRichiesto || "Intervento generico",
      dati: { ...dati },
    };
    await addDoc(collection(db, "storico_interventi"), nuovoIntervento);
    setSavedToast("✓ Salvato nello storico");
    setTimeout(() => setSavedToast(null), 2500);
  } catch (e) {
    console.error("Errore salvataggio storico:", e);
    setSavedToast("⚠ Errore nel salvataggio");
    setTimeout(() => setSavedToast(null), 2500);
  }
}




  const upd = (field) => (e) => setDati(p => ({ ...p, [field]: e.target.value }));
  const updVP = (field) => (e) => setDati(p => ({ ...p, vp: { ...p.vp, [field]: e.target.value } }));
  const updCheck = (key, val) => setDati(p => ({ ...p, vp: { ...p.vp, check: { ...p.vp.check, [key]: val } } }));

  useEffect(() => {
    [canvasClienteRef, canvasClienteVPRef].forEach(ref => {
      if (ref.current) {
        const ctx = ref.current.getContext("2d");
        ctx.strokeStyle = "#111";
        ctx.lineWidth = 2;
        ctx.lineCap = "round";
      }
    });
  }, [tab]);

  function getPos(canvas, e) {
    const rect = canvas.getBoundingClientRect();
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    return { x: clientX - rect.left, y: clientY - rect.top };
  }

  function startDraw(canvasRef, e) {
    e.preventDefault();
    isDrawingRef.current = true;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const pos = getPos(canvas, e);
    ctx.beginPath();
    ctx.moveTo(pos.x, pos.y);
  }

  function draw(canvasRef, e) {
    e.preventDefault();
    if (!isDrawingRef.current) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const pos = getPos(canvas, e);
    ctx.lineTo(pos.x, pos.y);
    ctx.stroke();
  }

  function stopDraw() { isDrawingRef.current = false; }

  function clearCanvas(canvasRef) {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.getContext("2d").clearRect(0, 0, canvas.width, canvas.height);
  }

  function aggiornaReparto(idx, field, val) {
    const n = [...dati.reparti]; n[idx] = { ...n[idx], [field]: val };
    setDati(p => ({ ...p, reparti: n }));
  }

  function aggiornaRicambio(idx, field, val) {
    const n = [...dati.ricambi]; n[idx] = { ...n[idx], [field]: val };
    setDati(p => ({ ...p, ricambi: n }));
  }

  // ===== BLOCCO FIRME (uguale in entrambe le pagine) =====
  const bloccoFirme = (canvasRef) => (
    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 12, marginTop: 8 }}>
      <div>
        <div style={{ ...labelS, marginBottom: 4 }}>Sigillo Identificativo Tecnico</div>
        <div style={{ border: "0.5px solid #ccc", borderRadius: 6, height: 80, background: "#fafafa", display: "flex", alignItems: "center", justifyContent: "center" }}>
          <span style={{ fontSize: 14, fontWeight: 700, color: "#222", letterSpacing: 2 }}>DMIS01</span>
        </div>
      </div>
      <FirmaTecnico />
      <FirmaBox
        label={canvasRef === canvasClienteRef ? "Timbro e Firma Cliente" : "Timbro e Firma Utente RT"}
        canvasRef={canvasRef}
        onClear={() => clearCanvas(canvasRef)}
        onStart={e => startDraw(canvasRef, e)}
        onDraw={e => draw(canvasRef, e)}
        onStop={stopDraw}
      />
    </div>
  );

  // ===== CONTENUTO PAGINA 1 =====
  const contentoPagina1 = (
    <div className="print-page">
      <Intestazione titolo="RAPPORTO INTERVENTO TECNICO SU REGISTRATORE TELEMATICO" sottotitolo="AI SENSI art. 8 del DM 23.03.83, art. 19 del DM 30.03.92 - Mod. 10.1 Rev. 2 del 10/10/2023" />
      <Privacy />
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8, marginBottom: 10 }}>
        <Field label="Richiesta N."><input style={iS} value={dati.richiestaNum} onChange={upd("richiestaNum")} /></Field>
        <Field label="Data Richiesta"><input style={iS} type="date" value={dati.dataRichiesta} onChange={upd("dataRichiesta")} /></Field>
        <Field label="Ora"><input style={iS} value={dati.ora} onChange={upd("ora")} /></Field>
      </div>
      <Sez>Dati Cliente</Sez>
      <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr", gap: 8, marginBottom: 8 }}>
        <Field label="Cliente"><input style={iS} value={cliente?.azienda || ""} readOnly /></Field>
        <Field label="P.IVA"><input style={iS} value={cliente?.piva || ""} readOnly /></Field>
        <Field label="Cod. Fiscale"><input style={iS} value={dati.codFiscale} onChange={upd("codFiscale")} /></Field>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr 0.5fr", gap: 8, marginBottom: 8 }}>
        <Field label="Sede Legale"><input style={iS} value={dati.sedeCliente} onChange={upd("sedeCliente")} /></Field>
        <Field label="CAP"><input style={iS} value={dati.capSede} onChange={upd("capSede")} /></Field>
        <Field label="Comune"><input style={iS} value={dati.comuneSede} onChange={upd("comuneSede")} /></Field>
        <Field label="Prov."><input style={iS} value={dati.provSede || cliente?.provincia || ""} onChange={upd("provSede")} maxLength={2} /></Field>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr 0.5fr", gap: 8, marginBottom: 8 }}>
        <Field label="Ubicazione Esercizio"><input style={iS} value={dati.ubicazione} onChange={upd("ubicazione")} /></Field>
        <Field label="CAP"><input style={iS} value={dati.capUbicazione} onChange={upd("capUbicazione")} /></Field>
        <Field label="Comune"><input style={iS} value={dati.comuneUbicazione} onChange={upd("comuneUbicazione")} /></Field>
        <Field label="Prov."><input style={iS} value={dati.provUbicazione} onChange={upd("provUbicazione")} maxLength={2} /></Field>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 8 }}>
        <Field label="Rif. Fattura SDI"><input style={iS} value={dati.rifSDI} onChange={upd("rifSDI")} /></Field>
        <Field label="PEC"><input style={iS} value={dati.pec} onChange={upd("pec")} /></Field>
      </div>
      <Sez>Dati Registratore Telematico</Sez>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 8, marginBottom: 8 }}>
        <Field label="Marca RT"><input style={iS} value={dati.marcaRT} onChange={upd("marcaRT")} /></Field>
        <Field label="Modello RT"><input style={iS} value={dati.modelloRT} onChange={upd("modelloRT")} /></Field>
        <Field label="Matricola RT"><input style={iS} value={dati.matricolaRT} onChange={upd("matricolaRT")} /></Field>
        <Field label="Ultimo firmware"><input style={iS} value={dati.ultimoFirmware} onChange={upd("ultimoFirmware")} /></Field>
      </div>
      <div style={{ display: "flex", gap: 16, marginBottom: 10, fontSize: 12 }}>
        <label style={{ cursor: "pointer" }}><input type="radio" checked={dati.ubicazioneFissa} onChange={() => setDati(p => ({ ...p, ubicazioneFissa: true }))} /> Sede fissa</label>
        <label style={{ cursor: "pointer" }}><input type="radio" checked={!dati.ubicazioneFissa} onChange={() => setDati(p => ({ ...p, ubicazioneFissa: false }))} /> Area pubblica</label>
      </div>
      <Sez>Intervento Richiesto</Sez>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 4, marginBottom: 8, fontSize: 12 }}>
        {["Censimento, attivazione e verifica periodica RT","Attivazione e verifica periodica RT","Verifica periodica RT","Disattivazione RT","Dismissione RT","Manutenzione straordinaria RT","Variazione dati intestazione/Ubicazione RT","Sostituzione memoria di dettaglio (EX DGFE)","Aggiornamento Firmware/Software RT","Altro (descrivere di seguito)"].map(v => (
          <label key={v} style={{ cursor: "pointer", display: "flex", alignItems: "center", gap: 5 }}>
            <input type="checkbox" checked={dati.interventoRichiesto === v} onChange={e => setDati(p => ({ ...p, interventoRichiesto: e.target.checked ? v : "" }))} /> {v}
          </label>
        ))}
      </div>
      <Field label="Descrizione libera intervento">
        <textarea style={{ ...iS, height: 50, resize: "vertical" }} value={dati.descrizioneIntervento} onChange={upd("descrizioneIntervento")} />
      </Field>
      <Sez>Luogo Esecuzione</Sez>
      <div style={{ display: "flex", gap: 16, marginBottom: 8, fontSize: 12 }}>
        {[["cliente","Presso il cliente"],["laboratorio","Presso il laboratorio con ritiro"],["remoto","Intervento da remoto"]].map(([v,l]) => (
          <label key={v} style={{ cursor: "pointer" }}><input type="radio" name="luogo" value={v} checked={dati.luogoIntervento === v} onChange={() => setDati(p => ({ ...p, luogoIntervento: v }))} /> {l}</label>
        ))}
      </div>
      <Sez>Riferimenti Commerciali</Sez>
      <div style={{ display: "flex", gap: 16, marginBottom: 8, fontSize: 12 }}>
        {[["pagamento","A pagamento"],["garanzia","In garanzia"],["abbonamento","Cliente in abbonamento"]].map(([v,l]) => (
          <label key={v} style={{ cursor: "pointer" }}><input type="radio" name="commerciale" value={v} checked={dati.riferimentiCommerciali === v} onChange={() => setDati(p => ({ ...p, riferimentiCommerciali: v }))} /> {l}</label>
        ))}
      </div>
      {dati.riferimentiCommerciali === "garanzia" && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 8 }}>
          <Field label="Rif. fattura n."><input style={iS} value={dati.rifFatturaGaranzia} onChange={upd("rifFatturaGaranzia")} /></Field>
          <Field label="Data"><input style={iS} type="date" value={dati.dataGaranzia} onChange={upd("dataGaranzia")} /></Field>
        </div>
      )}
      {dati.riferimentiCommerciali === "abbonamento" && (
        <Field label="Scadenza Abbonamento"><input style={{ ...iS, maxWidth: 180 }} type="date" value={dati.scadenzaAbbonamento} onChange={upd("scadenzaAbbonamento")} /></Field>
      )}
      <Sez>Programmazione Reparti RT</Sez>
      <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 11, marginBottom: 6 }}>
        <thead><tr style={{ background: "#f0f0f0" }}>
          {["N.","Descrizione Reparto","Natura IVA","Aliquota %","Bene","Servizio","Cod. ATECO"].map(h => (
            <th key={h} style={{ border: "0.5px solid #ccc", padding: "3px 5px", textAlign: "left" }}>{h}</th>
          ))}
        </tr></thead>
        <tbody>
          {dati.reparti.map((r, i) => (
            <tr key={i}>
              <td style={tdS}>{r.n}</td>
              <td style={tdS}><input style={{ ...iS, margin: 0 }} value={r.descrizione} onChange={e => aggiornaReparto(i,"descrizione",e.target.value)} /></td>
              <td style={tdS}><input style={{ ...iS, margin: 0, width: 60 }} value={r.naturaIVA} onChange={e => aggiornaReparto(i,"naturaIVA",e.target.value)} /></td>
              <td style={tdS}><input style={{ ...iS, margin: 0, width: 50 }} value={r.aliquota} onChange={e => aggiornaReparto(i,"aliquota",e.target.value)} /></td>
              <td style={{ ...tdS, textAlign: "center" }}><input type="checkbox" checked={r.bene} onChange={e => aggiornaReparto(i,"bene",e.target.checked)} /></td>
              <td style={{ ...tdS, textAlign: "center" }}><input type="checkbox" checked={r.servizio} onChange={e => aggiornaReparto(i,"servizio",e.target.checked)} /></td>
              <td style={tdS}><input style={{ ...iS, margin: 0 }} value={r.ateco} onChange={e => aggiornaReparto(i,"ateco",e.target.value)} /></td>
            </tr>
          ))}
        </tbody>
      </table>
      <div style={{ fontSize: 9, color: "#666", marginBottom: 10 }}>LEGENDA: N1-escluso / N2-non soggetto / N3-non imponibile / N4-esente / N5-regime margine / N6-altro / VI-ventilazione</div>
      <Sez>Costi Intervento</Sez>
      <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 11, marginBottom: 10 }}>
        <tbody>
          <tr>
            <td style={{ ...tdS, width: "35%" }}>1. Diritto di Chiamata</td>
            <td style={tdS}><input style={{ ...iS, margin: 0 }} placeholder="euro" value={dati.dirittoDiChiamata} onChange={upd("dirittoDiChiamata")} /></td>
            <td style={{ ...tdS, width: 50 }}>+ IVA</td>
          </tr>
          <tr>
            <td style={tdS}>2. Ore di lavoro</td>
            <td style={tdS}>
              <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
                <input style={{ ...iS, margin: 0, width: 50 }} placeholder="H" value={dati.orelavoro} onChange={upd("orelavoro")} />
                <span>x</span>
                <input style={{ ...iS, margin: 0, width: 70 }} placeholder="euro/h" value={dati.costoOrario} onChange={upd("costoOrario")} />
              </div>
            </td>
            <td style={tdS}>+ IVA</td>
          </tr>
          {dati.ricambi.map((r, i) => (
            <tr key={i}>
              <td style={tdS}>{i === 0 ? "3. Ricambi/Accessori" : ""}</td>
              <td style={tdS}>
                <div style={{ display: "flex", gap: 6 }}>
                  <input style={{ ...iS, margin: 0, flex: 2 }} placeholder="Articolo" value={r.articolo} onChange={e => aggiornaRicambio(i,"articolo",e.target.value)} />
                  <input style={{ ...iS, margin: 0, width: 45 }} placeholder="Q.ta" value={r.qta} onChange={e => aggiornaRicambio(i,"qta",e.target.value)} />
                  <input style={{ ...iS, margin: 0, width: 65 }} placeholder="euro" value={r.prezzo} onChange={e => aggiornaRicambio(i,"prezzo",e.target.value)} />
                </div>
              </td>
              <td style={tdS}>+ IVA</td>
            </tr>
          ))}
          <tr>
            <td style={tdS}>4. Verificazione Periodica RT</td>
            <td style={tdS}>
              <div style={{ display: "flex", gap: 12, fontSize: 12 }}>
                <label><input type="radio" checked={dati.verificazionePeriodica} onChange={() => setDati(p => ({ ...p, verificazionePeriodica: true }))} /> SI</label>
                <label><input type="radio" checked={!dati.verificazionePeriodica} onChange={() => setDati(p => ({ ...p, verificazionePeriodica: false }))} /> NO</label>
              </div>
            </td>
            <td style={tdS}>+ IVA</td>
          </tr>
          <tr style={{ background: "#f5f5f5", fontWeight: 600 }}>
            <td style={tdS}>Totale Intervento</td>
            <td style={tdS}><input style={{ ...iS, margin: 0, fontWeight: 600 }} placeholder="euro" value={dati.totaleIntervento} onChange={upd("totaleIntervento")} /></td>
            <td style={tdS}>+ IVA</td>
          </tr>
        </tbody>
      </table>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginBottom: 10 }}>
        <div>
          <div style={labelS}>Esito Intervento</div>
          <div style={{ display: "flex", gap: 12, fontSize: 12, marginTop: 4 }}>
            <label><input type="radio" checked={dati.esito === "positivo"} onChange={() => setDati(p => ({ ...p, esito: "positivo" }))} /> Positivo</label>
            <label><input type="radio" checked={dati.esito === "negativo"} onChange={() => setDati(p => ({ ...p, esito: "negativo" }))} /> Negativo</label>
          </div>
        </div>
        <div>
          <div style={labelS}>Pagamento Corrispettivo</div>
          <div style={{ display: "flex", gap: 12, fontSize: 12, marginTop: 4 }}>
            <label><input type="radio" checked={dati.pagamento} onChange={() => setDati(p => ({ ...p, pagamento: true }))} /> SI</label>
            <label><input type="radio" checked={!dati.pagamento} onChange={() => setDati(p => ({ ...p, pagamento: false }))} /> NO</label>
          </div>
          {!dati.pagamento && <input style={{ ...iS, marginTop: 4 }} placeholder="Motivazione" value={dati.motivazioneMancatoPagamento} onChange={upd("motivazioneMancatoPagamento")} />}
        </div>
      </div>
      <Sez>Questionario Soddisfazione</Sez>
      <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 11, marginBottom: 10 }}>
        <tbody>
          {[["valOperatori","Esperienza e capacita operatori"],["valServizio","Valutazione servizio"],["valQualitaPrezzo","Rapporto Qualita/Prezzo"]].map(([field,label]) => (
            <tr key={field}>
              <td style={{ ...tdS, width: "38%" }}>{label}</td>
              <td style={tdS}>
                <div style={{ display: "flex", gap: 8 }}>
                  {[["2","Scarso"],["4","Insufficiente"],["6","Accettabile"],["8","Buono"],["10","Ottimo"]].map(([v,l]) => (
                    <label key={v} style={{ cursor: "pointer", fontSize: 11 }}>
                      <input type="radio" name={field} value={v} checked={dati[field] === v} onChange={() => setDati(p => ({ ...p, [field]: v }))} /> {l}({v})
                    </label>
                  ))}
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <Field label="Rappresentante della ditta che ha richiesto l'intervento">
        <input style={iS} value={dati.rappresentante} onChange={upd("rappresentante")} />
      </Field>
      <Sez>Firme</Sez>
      {bloccoFirme(canvasClienteRef)}
    </div>
  );

  // ===== CONTENUTO PAGINA 2 =====
  const contentoPagina2 = (
    <div className="print-page">
      <Intestazione titolo="VERIFICAZIONE PERIODICA REGISTRATORE TELEMATICO" sottotitolo="Check-List - Allegato VIII (6.1 f) Mod. 10.2 Rev. 1 del 10/10/2023" />
      <Privacy />
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 8, marginBottom: 12 }}>
        <Field label="Nome Utente RT"><input style={iS} value={dati.vp.nomeUtente} onChange={updVP("nomeUtente")} /></Field>
        <Field label="P.IVA Utente RT"><input style={iS} value={dati.vp.pivaUtente} onChange={updVP("pivaUtente")} /></Field>
        <Field label="Modello RT"><input style={iS} value={dati.vp.modelloRT} onChange={updVP("modelloRT")} /></Field>
        <Field label="Matricola RT"><input style={iS} value={dati.vp.matricolaRT} onChange={updVP("matricolaRT")} /></Field>
      </div>
      <Sez>1. Esame Visivo RT</Sez>
      <CheckTable items={checkItems1} check={dati.vp.check} onChange={updCheck} />
      <div style={{ marginBottom: 10, fontSize: 12 }}>
        <div style={labelS}>1.4 Tipologia sigillo fiscale</div>
        <div style={{ display: "flex", gap: 16, marginTop: 4 }}>
          {[["targhetta","Targhetta adesiva"],["percussione","Percussione (piombo/PVC)"],["tamper","Tamper"]].map(([v,l]) => (
            <label key={v} style={{ cursor: "pointer" }}>
              <input type="radio" name="sigillo" value={v} checked={dati.vp.tipoSigillo === v} onChange={() => setDati(p => ({ ...p, vp: { ...p.vp, tipoSigillo: v } }))} /> {l}
            </label>
          ))}
        </div>
      </div>
      <Sez>2. Prove di Funzionamento RT</Sez>
      <CheckTable items={checkItems2} check={dati.vp.check} onChange={updCheck} extra={{
        "2.2": <Field label="Versione identificata su RT"><input style={{ ...iS, marginTop: 2 }} value={dati.vp.versioneFirmwareRT} onChange={updVP("versioneFirmwareRT")} /></Field>,
        "2.4": <Field label="Versione installata"><input style={{ ...iS, marginTop: 2 }} value={dati.vp.versioneInstallata} onChange={updVP("versioneInstallata")} /></Field>,
      }} />
      <Sez>3. Prove RT su Aree Pubbliche</Sez>
      <div style={{ marginBottom: 8 }}>
        <label style={{ fontSize: 12, cursor: "pointer" }}>
          <input type="checkbox" checked={!!dati.vp.areePubliche} onChange={e => setDati(p => ({ ...p, vp: { ...p.vp, areePubliche: e.target.checked } }))} /> Non applicabile
        </label>
      </div>
      {!dati.vp.areePubliche && <CheckTable items={checkItems3} check={dati.vp.check} onChange={updCheck} />}
      <Sez>4. Chiusura Intervento RT</Sez>
      <CheckTable items={checkItems4} check={dati.vp.check} onChange={updCheck} />
      <Sez>Esito Verificazione Periodica</Sez>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 12, marginBottom: 12 }}>
        <div>
          <div style={labelS}>Esito VP</div>
          <div style={{ display: "flex", gap: 12, fontSize: 12, marginTop: 4 }}>
            <label><input type="radio" checked={dati.vp.esitoVP === "positivo"} onChange={() => setDati(p => ({ ...p, vp: { ...p.vp, esitoVP: "positivo" } }))} /> Positivo</label>
            <label><input type="radio" checked={dati.vp.esitoVP === "negativo"} onChange={() => setDati(p => ({ ...p, vp: { ...p.vp, esitoVP: "negativo" } }))} /> Negativo</label>
          </div>
        </div>
        <Field label="Doc. gestionale chiusura n."><input style={iS} value={dati.vp.docChiusura} onChange={updVP("docChiusura")} /></Field>
        <Field label="Scadenza VP"><input style={iS} type="date" value={dati.vp.scadenzaVP} onChange={updVP("scadenzaVP")} /></Field>
      </div>
      <Field label="Data Verificazione">
        <input style={{ ...iS, maxWidth: 180 }} type="date" value={dati.vp.dataVP} onChange={updVP("dataVP")} />
      </Field>
      <Sez>Firme</Sez>
      {bloccoFirme(canvasClienteVPRef)}
    </div>
  );

  return (
    <>
      <style>{`
        @media print {
          .no-print { display: none !important; }
          .print-page { page-break-after: always; padding: 8px 16px !important; }
          .print-page:last-child { page-break-after: auto; }
          .modal-overlay { position: static !important; background: none !important; overflow: visible !important; padding: 0 !important; }
          .modal-box { max-height: none !important; overflow: visible !important; box-shadow: none !important; border: none !important; padding: 0 !important; max-width: 100% !important; width: 100% !important; margin: 0 !important; border-radius: 0 !important; }
          .screen-only { display: none !important; }
          .print-both { display: block !important; }
        }
        @media screen { .print-both { display: none; } }
      `}</style>

      <div
        className="modal-overlay"
        style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.5)", zIndex: 200, display: "flex", alignItems: "flex-start", justifyContent: "center", overflowY: "auto", padding: "1rem" }}
        onClick={e => { if (e.target === e.currentTarget) onClose(); }}
      >
        <div
          className="modal-box"
          style={{ background: "#fff", borderRadius: 12, width: "100%", maxWidth: 900, margin: "1rem auto", boxShadow: "0 8px 32px rgba(0,0,0,0.2)" }}
          onClick={e => e.stopPropagation()}
        >
          {/* Header */}
          <div className="no-print" style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "1rem 1.5rem", borderBottom: "0.5px solid #e0e0e0", borderRadius: "12px 12px 0 0", background: "#fff" }}>
            <div>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <span style={{ fontSize: 15, fontWeight: 600 }}>Modulo Intervento Tecnico</span>
                {solaLettura && (
                  <span style={{ fontSize: 11, background: "#faeeda", color: "#854f0b", padding: "2px 8px", borderRadius: 99, fontWeight: 500 }}>
                    sola lettura
                  </span>
                )}
              </div>
              <div style={{ fontSize: 12, color: "#888" }}>{cliente?.azienda}{cliente?.citta ? " - " + cliente.citta : ""}</div>
            </div>
            <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
              {savedToast && (
                <span style={{ fontSize: 12, color: savedToast.startsWith("✓") ? "#1d9e75" : "#e24b4a", fontWeight: 500 }}>
                  {savedToast}
                </span>
              )}
              {!solaLettura && (
                <button onClick={salvaStorico} style={{ ...btnStyle, background: "#1d9e75", color: "#fff", border: "none" }}>💾 Salva storico</button>
              )}
              <button onClick={() => window.print()} style={{ ...btnStyle, background: "#185fa5", color: "#fff", border: "none" }}>🖨 Stampa / PDF</button>
              <button onClick={onClose} style={btnStyle}>✕ Chiudi</button>
            </div>
          </div>

          {/* Tabs */}
          <div className="no-print" style={{ display: "flex", borderBottom: "0.5px solid #e0e0e0", padding: "0 1.5rem", background: "#fff" }}>
            {[["rapporto","Pag. 1 - Rapporto Intervento"],["checklist","Pag. 2 - Verificazione Periodica"]].map(([t,l]) => (
              <button key={t} onClick={() => setTab(t)} style={{ padding: "10px 20px", fontSize: 13, border: "none", background: "none", cursor: "pointer", color: tab === t ? "#111" : "#888", borderBottom: tab === t ? "2px solid #111" : "2px solid transparent", fontWeight: tab === t ? 600 : 400 }}>
                {l}
              </button>
            ))}
          </div>

          {/* Contenuto schermo: solo tab attivo */}
          <div className="screen-only" style={{ padding: "1.5rem", maxHeight: "70vh", overflowY: "auto" }}>
            {tab === "rapporto" ? contentoPagina1 : contentoPagina2}
          </div>

          {/* Contenuto stampa: entrambe le pagine */}
          <div className="print-both">
            {contentoPagina1}
            {contentoPagina2}
          </div>
        </div>
      </div>
    </>
  );
}
